// ---- OAuth flow state (short-lived, one row per in-flight authorization) ----

export const getOauthState = queryGeneric({
  args: { portalSecret: v.string(), key: v.string() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const row = await ctx.db
      .query("oauthStates")
      .withIndex("by_key", (q) => q.eq("key", args.key))
      .unique();
    if (!row || row.expiresAt <= now()) return null;
    return row.stateJson;
  },
});

export const setOauthState = mutationGeneric({
  args: { portalSecret: v.string(), key: v.string(), stateJson: v.string(), ttlMs: v.number() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    if (!Number.isSafeInteger(args.ttlMs) || args.ttlMs <= 0 || args.ttlMs > 3_600_000) {
      throw new Error("INVALID_STATE_TTL");
    }
    const timestamp = now();
    const existing = await ctx.db
      .query("oauthStates")
      .withIndex("by_key", (q) => q.eq("key", args.key))
      .unique();
    const record = { stateJson: args.stateJson, expiresAt: timestamp + args.ttlMs };
    if (existing) {
      await ctx.db.patch(existing._id, record);
      return existing._id;
    }
    return await ctx.db.insert("oauthStates", { key: args.key, createdAt: timestamp, ...record });
  },
});

export const deleteOauthState = mutationGeneric({
  args: { portalSecret: v.string(), key: v.string() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const row = await ctx.db
      .query("oauthStates")
      .withIndex("by_key", (q) => q.eq("key", args.key))
      .unique();
    if (row) await ctx.db.delete(row._id);
  },
});

// ---- OAuth sessions (durable, keyed by DID) ----

export const getOauthSession = queryGeneric({
  args: { portalSecret: v.string(), did: v.string() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const row = await ctx.db
      .query("oauthSessions")
      .withIndex("by_did", (q) => q.eq("did", args.did))
      .unique();
    return row?.sessionJson ?? null;
  },
});

export const setOauthSession = mutationGeneric({
  args: { portalSecret: v.string(), did: v.string(), sessionJson: v.string() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const timestamp = now();
    const existing = await ctx.db
      .query("oauthSessions")
      .withIndex("by_did", (q) => q.eq("did", args.did))
      .unique();
    if (existing) {
      await ctx.db.patch(existing._id, { sessionJson: args.sessionJson, updatedAt: timestamp });
      return existing._id;
    }
    return await ctx.db.insert("oauthSessions", {
      did: args.did,
      sessionJson: args.sessionJson,
      createdAt: timestamp,
      updatedAt: timestamp,
    });
  },
});

/** Removes the OAuth session and every browser session riding on it. */
export const deleteOauthSession = mutationGeneric({
  args: { portalSecret: v.string(), did: v.string() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const row = await ctx.db
      .query("oauthSessions")
      .withIndex("by_did", (q) => q.eq("did", args.did))
      .unique();
    if (row) await ctx.db.delete(row._id);
    const sessions = await ctx.db
      .query("portalSessions")
      .withIndex("by_did", (q) => q.eq("did", args.did))
      .take(256);
    for (const session of sessions) await ctx.db.delete(session._id);
  },
});

// ---- Portal browser sessions ----

export const createPortalSession = mutationGeneric({
  args: {
    portalSecret: v.string(),
    sessionId: v.string(),
    did: v.string(),
    csrfToken: v.string(),
    ttlMs: v.number(),
  },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    if (!Number.isSafeInteger(args.ttlMs) || args.ttlMs <= 0 || args.ttlMs > 30 * 24 * 60 * 60 * 1000) {
      throw new Error("INVALID_SESSION_TTL");
    }
    const timestamp = now();
    return await ctx.db.insert("portalSessions", {
      sessionId: args.sessionId,
      did: args.did,
      csrfToken: args.csrfToken,
      createdAt: timestamp,
      expiresAt: timestamp + args.ttlMs,
    });
  },
});

export const getPortalSession = queryGeneric({
  args: { portalSecret: v.string(), sessionId: v.string() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const row = await ctx.db
      .query("portalSessions")
      .withIndex("by_session", (q) => q.eq("sessionId", args.sessionId))
      .unique();
    if (!row || row.expiresAt <= now()) return null;
    return { did: row.did, csrfToken: row.csrfToken, expiresAt: row.expiresAt };
  },
});

export const deletePortalSession = mutationGeneric({
  args: { portalSecret: v.string(), sessionId: v.string() },
  handler: async (ctx, args) => {
    requirePortalSecret(args.portalSecret);
    const row = await ctx.db
      .query("portalSessions")
      .withIndex("by_session", (q) => q.eq("sessionId", args.sessionId))
      .unique();
    if (!row) return null;
    await ctx.db.delete(row._id);
    return row.did;
  },
});

/** Cron target: drops expired flow state and browser sessions. */
export const purgeExpired = mutationGeneric({
  args: {},
  handler: async (ctx) => {
    const cutoff = now();
    let removed = 0;
    const states = await ctx.db
      .query("oauthStates")
      .withIndex("by_expiry", (q) => q.lt("expiresAt", cutoff))
      .take(512);
    for (const state of states) {
      await ctx.db.delete(state._id);
      removed += 1;
    }
    const sessions = await ctx.db
      .query("portalSessions")
      .withIndex("by_expiry", (q) => q.lt("expiresAt", cutoff))
      .take(512);
    for (const session of sessions) {
      await ctx.db.delete(session._id);
      removed += 1;
    }
    return { removed };
  },
});
