  const handle = publicText(value.handle);
  if (displayName === undefined || handle === undefined) return null;
  let avatarUrl: string | null = null;
  if (value.avatarUrl !== null) {
    if (typeof value.avatarUrl !== "string" || value.avatarUrl.length > 2048) return null;
    try {
      const url = new URL(value.avatarUrl);
      if (url.origin !== pdsOrigin || url.username || url.password || url.hash ||
