  test("wrong portal secret and wrong request owner cannot write a public profile", async () => {
    const f = await harness();
    await f.store.createPublicAuthorizationRequest({ requestId: "owner", did: DID, clientId: TWYNE_URL, redirectUri: `${TWYNE_URL}/auth/notorganic/`, codeChallenge: "v".repeat(43), scope: "wallet:read", environment: "browser" });
