describe("verified public profile producer → Twyne redemption", () => {
  test("portal approval persists actual PDS fields and the DPoP gateway DTO reaches Twyne", async () => {
    const f = await harness();
    const verified = await f.authorization({ displayName: "Browser spoof", publicProfile: JSON.stringify({ did: OTHER_DID, avatarUrl: "https://attacker.test/image" }) });
    expect(verified).toMatchObject({ did: DID, handle: "morgan.notorganic.test", displayName: "Morgan Vale", avatarUrl: AVATAR_URL });
    expect(verified.sessionVersion).toBeInteger();
    const row = await f.convex.run(ctx => ctx.db.query("oauthSessions").withIndex("by_did", q => q.eq("did", DID)).unique());
    expect(row?.publicProfile).toEqual({ did: DID, displayName: "Morgan Vale", handle: "morgan.notorganic.test", avatarUrl: AVATAR_URL });
    expect(f.profileReads).toContain("/xrpc/com.atproto.repo.getRecord");
    const dto = f.gatewayDtos.at(-1)!;
    expect(dto.account).toMatchObject({ did: DID, displayName: "Morgan Vale", avatarUrl: AVATAR_URL });
    const serialized = JSON.stringify({ dto, verified });
    for (const privateField of ["sessionJson", "access_token", "refresh_token", "dpopKeyJwk", "synthetic-private", "private-key-never", "Browser spoof", "attacker.test"]) expect(serialized).not.toContain(privateField);
    const avatar = new URL(verified.avatarUrl!);
    expect(avatar.protocol).toBe("https:");
    expect(avatar.origin).toBe(PDS_URL);
    expect(avatar.pathname).toBe("/xrpc/com.atproto.sync.getBlob");
    expect(avatar.searchParams.get("did")).toBe(DID);
    expect(verified.avatarUrl).not.toContain("/api/session/avatar");
  });

  test("the real producer works before a didAccounts row exists", async () => {
    const f = await harness({ missingAccount: true });
    expect(await f.authorization()).toMatchObject({ did: DID, displayName: "Morgan Vale", avatarUrl: AVATAR_URL });
    expect(await f.convex.run(ctx => ctx.db.query("didAccounts").collect())).toEqual([]);
  });

  test("a later approval refreshes the name and explicitly clears a removed picture", async () => {
    const f = await harness();
    expect((await f.authorization()).avatarUrl).toBe(AVATAR_URL);
    f.setRecord({ uri: `at://${DID}/app.bsky.actor.profile/self`, value: { $type: "app.bsky.actor.profile", displayName: "M. Vale" } });
    expect(await f.authorization()).toMatchObject({ displayName: "M. Vale", avatarUrl: null });
  });

  test("an absent profile falls back to the handle and clears stale public photo/name", async () => {
    const f = await harness();
    await f.authorization();
    f.setRecord({ error: "RecordNotFound" }, 400);
    const verified = await f.authorization();
    expect(verified).toMatchObject({ did: DID, handle: "morgan.notorganic.test", avatarUrl: null });
    expect(verified.displayName).toBeUndefined();
  });

  test("unavailable profile data leaves sign-in usable without inventing profile claims", async () => {
    const f = await harness();
    f.setRecord({ error: "Unavailable" }, 503);
    const verified = await f.authorization();
    expect(verified.handle).toBe("morgan.notorganic.test");
    expect(verified.displayName).toBeUndefined();
    expect(verified.avatarUrl).toBeUndefined();
  });

  test("a profile record belonging to another DID cannot populate the gateway or Twyne", async () => {
    const f = await harness();
    f.setRecord({ uri: `at://${OTHER_DID}/app.bsky.actor.profile/self`, value: { $type: "app.bsky.actor.profile", displayName: "Another Writer" } });
    const verified = await f.authorization();
    expect(verified.displayName).toBeUndefined();
    expect(verified.avatarUrl).toBeUndefined();
    expect(JSON.stringify(f.gatewayDtos)).not.toContain("Another Writer");
  });

  test("email-like names and unverified image strings never become public claims", async () => {
    const f = await harness();
    f.setRecord({ uri: `at://${DID}/app.bsky.actor.profile/self`, value: { $type: "app.bsky.actor.profile", displayName: "synthetic-private@example.test", avatar: "https://attacker.test/image" } });
    const verified = await f.authorization();
    expect(verified.displayName).toBeUndefined();
    expect(verified.avatarUrl).toBeNull();
    expect(JSON.stringify(f.gatewayDtos)).not.toContain("synthetic-private");
  });

  test("OAuth subject or unsafe resource metadata cannot publish cross-product claims", async () => {
    for (const [subject, resource] of [[OTHER_DID, PDS_URL], [DID, "http://pds.notorganic.test"], [DID, "REDACTED"], [DID, `${PDS_URL}/untrusted-path`]]) {
      const f = await harness();
      f.setTokenInfo(subject!, resource!);
      const verified = await f.authorization();
      expect(verified.displayName).toBeUndefined();
      expect(verified.avatarUrl).toBeUndefined();
    }
  });

  test("OAuth credential rotation preserves the separate public projection", async () => {
    const f = await harness();
    await f.authorization();
    await f.store.setOauthSession(DID, storedSession());
