describe("profile persistence and DTO isolation", () => {
  test("invalid subject/blob claims cannot burn a request or issue its code", async () => {
    for (const changed of [
      { did: OTHER_DID },
      { avatarUrl: `${PDS_URL}/xrpc/com.atproto.sync.getBlob?did=${OTHER_DID}&cid=${CID}` },
      { avatarUrl: `https://attacker.test/xrpc/com.atproto.sync.getBlob?did=${DID}&cid=${CID}` },
      { avatarUrl: `${PDS_URL}/api/session/avatar?cid=${CID}` },
      { avatarUrl: AVATAR_URL + "&token=private" },
      { displayName: "synthetic-private@example.test" },
    ]) {
      const f = await harness();
      await f.store.createPublicAuthorizationRequest({ requestId: "reject-profile", did: DID, clientId: TWYNE_URL, redirectUri: `${TWYNE_URL}/auth/notorganic/`, codeChallenge: "v".repeat(43), scope: "wallet:read", environment: "browser" });
      const publicProfile: PublicProfile = { did: DID, displayName: "Morgan Vale", handle: "morgan.notorganic.test", avatarUrl: AVATAR_URL, ...changed };
      await expect(f.store.approvePublicAuthorizationRequest({ requestId: "reject-profile", did: DID, codeHash: "not-issued", publicProfile })).rejects.toThrow("AUTHORIZATION_PROFILE_INVALID");
      expect(await f.convex.run(ctx => ctx.db.query("publicAuthorizationRequests").collect())).toHaveLength(1);
      expect(await f.convex.run(ctx => ctx.db.query("publicAuthorizationCodes").collect())).toHaveLength(0);
      expect((await f.readAccount()).account).not.toHaveProperty("displayName");
    }
