    await expect(f.convex.mutation(approve, { ...input, portalSecret: "wrong" })).rejects.toThrow();
    await expect(f.convex.mutation(approve, { ...input, did: OTHER_DID })).rejects.toThrow("AUTHORIZATION_REQUEST_INVALID");
    expect((await f.readAccount()).account).not.toHaveProperty("displayName");
  });

  test("malformed or mismatched stored OAuth subjects fail closed in gateway DTOs", async () => {
    for (const sessionJson of ["not JSON", storedSession(OTHER_DID), storedSession(DID, "http://pds.notorganic.test"), storedSession(DID, "https://other-pds.test")]) {
      const f = await harness();
      await f.authorization();
      await f.store.setOauthSession(DID, sessionJson);
      const dto = await f.readAccount();
      expect(dto.account.handle).toBe("morgan.notorganic.test");
      expect(dto.account).not.toHaveProperty("displayName");
      expect(dto.account).not.toHaveProperty("avatarUrl");
      expect(JSON.stringify(dto)).not.toContain("sessionJson");
    }
  });

  test("another account never receives this OAuth projection", async () => {
    const f = await harness();
    await f.authorization();
    expect((await f.convex.query(accountQuery, { serviceSecret: GATEWAY_SECRET, did: OTHER_DID })).account).toBeNull();
  });
});
