import type { SessionAdapter } from "@notorganic/session";
import type { SessionProfile } from "../src/api";
import { publicPdsOrigin, type PublicProfile } from "../../../convex/publicProfile";

type ProfileOAuthSession = Pick<OAuthSession, "did" | "fetchHandler"> & Partial<Pick<OAuthSession, "getTokenInfo">>;

export interface ProfileOAuth {
  restore?(
    did: string,
    refresh?: boolean | "auto",
  ): Promise<ProfileOAuthSession>;
}

interface AvatarBlob {
  cid: string;
  mimeType: string;
  size: number;
}

export interface SessionProfileResult {
  profile: SessionProfile | null;
  /** Public absolute URLs for other products; never a portal-cookie URL. */
  publicProfile?: PublicProfile;
  /** Server-only: never serialize OAuth sessions or credentials into the response. */
  oauthSession?: ProfileOAuthSession;
  avatar?: AvatarBlob;
}

export const MAX_AVATAR_BYTES = 1_000_000;
// Matches app.bsky.actor.profile's avatar blob contract.
const IMAGE_TYPES = new Set(["image/jpeg", "image/png"]);
const EMAIL_PATTERN = /[^\s<>()@]+@[^\s<>()@]+/;

function object(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function publicText(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const text = value.trim().replace(/\s+/g, " ");
  return text &&
    text.length <= 256 &&
    !EMAIL_PATTERN.test(text) &&
    !/[\x00-\x1f\x7f]/.test(text)
    ? text
    : null;
}

function avatarBlob(value: unknown): AvatarBlob | undefined {
  const blob = object(value);
  const ref = object(blob?.ref);
  if (
    blob?.$type !== "blob" ||
    typeof ref?.$link !== "string" ||
    !/^[a-zA-Z0-9]{20,200}$/.test(ref.$link) ||
    typeof blob.mimeType !== "string" ||
    !IMAGE_TYPES.has(blob.mimeType) ||
    typeof blob.size !== "number" ||
    !Number.isSafeInteger(blob.size) ||
    blob.size < 1 ||
    blob.size > MAX_AVATAR_BYTES
  )
    return undefined;
  return { cid: ref.$link, mimeType: blob.mimeType, size: blob.size };
}

/**
 * Account rows currently store a handle, not an avatar or a display name.
 * Read those optional fields from the signed-in DID's actual ATProto profile
 * record, through its server-held OAuth session. No browser identity arguments,
 * email hashes, product mappings, or OAuth JSON are exposed in the projection.
 */
export async function readSessionProfile(
  did: string,
  {
    adapter,
    oauth,
  }: { adapter: Pick<SessionAdapter, "clientFor">; oauth: ProfileOAuth },
): Promise<SessionProfileResult> {
  let handle: string | null = null;
  try {
    const result = object(await adapter.clientFor(did).account.retrieve());
    const account = object(result?.account);
    // A missing row is normal immediately after OAuth; a conflicting row isn't.
    if (
      result?.account != null &&
      (!account || account.did !== did || account.deletedAt != null)
    )
      return { profile: null };
    handle = publicText(account?.handle);
  } catch {
    // An identity mismatch or unavailable account service cannot yield a profile.
    return { profile: null };
  }

  const fallback = (): SessionProfileResult => ({
    profile: handle ? { handle } : null,
  });
  if (!oauth.restore) return fallback();

  try {
    const session = await oauth.restore(did, false);
    if (session.did !== did) return { profile: null };
    let pdsOrigin: string | null = null;
    if (session.getTokenInfo) {
      const info = await session.getTokenInfo(false);
      if (info.sub !== did) return { profile: null };
      pdsOrigin = publicPdsOrigin(info.aud);
    }
    const publicProjection = (displayName: string | null, avatar?: AvatarBlob): PublicProfile | undefined => pdsOrigin ? {
      did, displayName, handle,
      avatarUrl: avatar ? `${pdsOrigin}/xrpc/com.atproto.sync.getBlob?${new URLSearchParams({ did, cid: avatar.cid })}` : null,
    } : undefined;
    const signal = AbortSignal.timeout(3_000);
    const [repoResponse, recordResponse] = await Promise.all([
      session.fetchHandler(
        `/xrpc/com.atproto.repo.describeRepo?repo=${encodeURIComponent(did)}`,
        { signal, redirect: "error" },
      ),
      session.fetchHandler(
        `/xrpc/com.atproto.repo.getRecord?repo=${encodeURIComponent(did)}&collection=app.bsky.actor.profile&rkey=self`,
        { signal, redirect: "error" },
      ),
    ]);
    if (repoResponse.ok) {
      const repo = object(await repoResponse.json());
      if (repo?.did !== did) return { profile: null };
      handle = publicText(repo.handle) ?? handle;
    }
    if (!recordResponse.ok) {
      const error = await recordResponse.json().catch(() => null);
      const absent = recordResponse.status === 404 || object(error)?.error === "RecordNotFound";
      const publicProfile = absent && repoResponse.ok ? publicProjection(null) : undefined;
      return { ...fallback(), ...(publicProfile ? { publicProfile } : {}) };
    }
    const record = object(await recordResponse.json());
    const value = object(record?.value);
    if (
      record?.uri !== `at://${did}/app.bsky.actor.profile/self` ||
      value?.$type !== "app.bsky.actor.profile"
    )
      return { profile: null };
    const displayName = publicText(value.displayName);
    const avatar = avatarBlob(value.avatar);
    const publicProfile = publicProjection(displayName, avatar);
    return {
      ...(publicProfile ? { publicProfile } : {}),
      profile:
        displayName || handle || avatar
          ? {
              displayName,
              handle,
              // The CSP permits self-hosted images. The route verifies this CID against
              // the current authenticated profile before reading the blob from its PDS.
              avatarUrl: avatar
                ? `/api/session/avatar?cid=${encodeURIComponent(avatar.cid)}`
                : null,
            }
          : null,
      ...(avatar ? { avatar, oauthSession: session } : {}),
    };
  } catch {
    // Missing/expired OAuth or absent profiles must not sign the user out.
    return fallback();
  }
}

export async function readSessionAvatar(
  result: SessionProfileResult,
  requestedCid: string,
): Promise<Response | null> {
  if (
    !result.oauthSession ||
    !result.avatar ||
    requestedCid !== result.avatar.cid
  )
    return null;
  try {
    const response = await result.oauthSession.fetchHandler(
      `/xrpc/com.atproto.sync.getBlob?did=${encodeURIComponent(result.oauthSession.did)}&cid=${encodeURIComponent(result.avatar.cid)}`,
      { signal: AbortSignal.timeout(3_000), redirect: "error" },
    );
    if (
      !response.ok ||
      response.headers
        .get("content-type")
        ?.split(";")[0]
        ?.trim()
        .toLowerCase() !== result.avatar.mimeType
    )
      return null;
    if (!response.body) return null;
    const reader = response.body.getReader();
    const chunks: Uint8Array[] = [];
    let size = 0;
    try {
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        size += value.byteLength;
        if (size > MAX_AVATAR_BYTES || size > result.avatar.size) {
          await reader.cancel();
          return null;
        }
        chunks.push(value);
      }
    } finally {
      reader.releaseLock();
    }
    if (size !== result.avatar.size) return null;
    const body = new Uint8Array(size);
    let offset = 0;
    for (const chunk of chunks) {
      body.set(chunk, offset);
      offset += chunk.byteLength;
    }
    return new Response(body, {
      headers: {
        "Content-Type": result.avatar.mimeType,
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return null;
  }
}
