/** Only public identity metadata. No OAuth credentials or email belong here. */
export const publicProfileValidator = v.object({
  did: v.string(),
  displayName: v.union(v.string(), v.null()),
  handle: v.union(v.string(), v.null()),
  avatarUrl: v.union(v.string(), v.null()),
});
export type PublicProfile = Infer<typeof publicProfileValidator>;

function object(value: unknown): Record<string, unknown> | null {
  return value !== null && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown> : null;
}

export function publicPdsOrigin(value: unknown): string | null {
  if (typeof value !== "string" || value.length > 2048) return null;
  try {
    const url = new URL(value);
    return url.protocol === "https:" && !url.username && !url.password &&
      url.pathname === "/" && !url.search && !url.hash ? url.origin : null;
  } catch { return null; }
}

function publicText(value: unknown): string | null | undefined {
  if (value === null) return null;
  if (typeof value !== "string") return undefined;
  const text = value.trim();
  if (text.length > 256 || /[^\s<>()@]+@[^\s<>()@]+/.test(text) ||
      Array.from(text).some(char => char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127)) return undefined;
  return text || null;
}

/**
 * Both approval and gateway reads bind the projection to the stored OAuth
 * subject/resource. Parsing stays server-side; only whitelisted fields leave.
 */
export function publicProfileForSession(
  profile: unknown, did: string, sessionJson: string,
): Omit<PublicProfile, "did"> | null {
  const value = object(profile);
  if (!value || value.did !== did) return null;
  let tokenSet: Record<string, unknown> | null;
  try { tokenSet = object(object(JSON.parse(sessionJson))?.tokenSet); }
  catch { return null; }
  if (tokenSet?.sub !== did) return null;
  const pdsOrigin = publicPdsOrigin(tokenSet.aud);
  if (!pdsOrigin) return null;
  const displayName = publicText(value.displayName);
  const handle = publicText(value.handle);
  if (displayName === undefined || handle === undefined) return null;
  let avatarUrl: string | null = null;
  if (value.avatarUrl !== null) {
    if (typeof value.avatarUrl !== "string" || value.avatarUrl.length > 2048) return null;
    try {
      const url = new URL(value.avatarUrl);
      if (url.origin !== pdsOrigin || url.username || url.password || url.hash ||
          url.pathname !== "/xrpc/com.atproto.sync.getBlob" ||
          [...url.searchParams].length !== 2 || url.searchParams.get("did") !== did ||
          !/^[a-zA-Z0-9]{20,200}$/.test(url.searchParams.get("cid") ?? "")) return null;
      avatarUrl = url.href;
    } catch { return null; }
  }
  return { displayName, handle, avatarUrl };
}
