 * Not Organic sign-in — the only way into a Twyne account.
 *
 * The browser runs PKCE against `id.notorganic.info` and posts the returned
 * code + verifier here. The code is redeemed server-side (no gateway CORS, no
 * caller-supplied DID), the verified DID is mapped to a Better Auth user via a
 * `notorganic` account row, and a normal Better Auth session is issued so every
 * Convex query keeps authenticating the way it always has.
 */
import type { BetterAuthPlugin } from "better-auth";
import { APIError, createAuthEndpoint } from "better-auth/api";
import { setSessionCookie } from "better-auth/cookies";
import { z } from "zod";
import { redeemProviderLink } from "./providerLink";

export const NOTORGANIC_PROVIDER_ID = "notorganic";
export const NOTORGANIC_SIGN_IN_PATH = "/auth/notorganic/";

export interface VerifiedNotOrganicAccount {
  did: string;
  sessionVersion: number;
  handle?: string;
  displayName?: string;
  /** Undefined leaves the stored avatar alone; null removes it. */
  avatarUrl?: string | null;
}

/** Preserve profile fields from the same DPoP-authenticated account proof. */
export async function redeemNotOrganicSignIn(
  input: { code: string; verifier: string },
  origin: string,
  issuer: string,
  fetchImpl: typeof fetch = fetch,
): Promise<VerifiedNotOrganicAccount> {
  let account: Record<string, unknown> | null = null;
  const verified = await redeemProviderLink(
    input,
    origin,
    issuer,
    (async (input: RequestInfo | URL, init?: RequestInit) => {
      const response = await fetchImpl(input, init);
      const url = input instanceof Request ? input.url : String(input);
      if (url === `${issuer}/v1/account` && response.ok) {
        const body: unknown = await response.clone().json();
        if (body !== null && typeof body === "object" && "account" in body) {
          const value = body.account;
          if (
            value !== null &&
            typeof value === "object" &&
            !Array.isArray(value)
          ) {
            account = value as Record<string, unknown>;
          }
        }
      }
      return response;
    }) as typeof fetch,
    NOTORGANIC_SIGN_IN_PATH,
  );
  // redeemProviderLink already checked the account DID, token product and
  // session version. Optional profile data never establishes identity.
  const profile = account as Record<string, unknown> | null;
  const displayName =
    typeof profile?.displayName === "string"
      ? profile.displayName.trim().slice(0, 256)
      : undefined;
  const avatarUrl = safeAvatarUrl(profile?.avatarUrl);
  return {
    ...verified,
    ...(displayName ? { displayName } : {}),
    ...(avatarUrl !== undefined ? { avatarUrl } : {}),
  };
}

function safeAvatarUrl(value: unknown): string | null | undefined {
  if (value === null || value === "") return null;
  if (typeof value !== "string" || value.length > 2048) return undefined;
  try {
    const url = new URL(value);
    return url.protocol === "https:" && !url.username && !url.password
      ? url.href
      : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Better Auth requires a unique email. Not Organic accounts don't hand one
 * over, so the user row carries an undeliverable, DID-derived placeholder.
 */
export async function placeholderEmailForDid(did: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(did),
  );
  const hex = Array.from(new Uint8Array(digest).slice(0, 16), (byte) =>
    byte.toString(16).padStart(2, "0"),
  ).join("");
  return `${hex}@notorganic.invalid`;
}

