  exportJWK,
  generateKeyPair,
  SignJWT,
  type CryptoKey,
  type JWK,
} from "jose";
import type {
  DpopProofFactory,
  DpopProofInput,
} from "./types";

export interface DpopKeyPair {
  privateKey: CryptoKey;
  publicKey: CryptoKey;
  publicJwk: JWK;
}

function base64url(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

async function accessTokenHash(accessToken: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(accessToken),
  );
  return base64url(new Uint8Array(digest));
}

export async function createDpopKeyPair(): Promise<DpopKeyPair> {
  const { privateKey, publicKey } = await generateKeyPair("ES256", {
    extractable: true,
  });
  return {
    privateKey,
    publicKey,
    publicJwk: await exportJWK(publicKey),
  };
}

export function createDpopProofFactory(input: {
  privateKey: CryptoKey;
  publicJwk: JWK;
}): DpopProofFactory {
  return async ({
    url,
    method,
    accessToken,
  }: DpopProofInput): Promise<string> =>
    new SignJWT({
      htm: method.toUpperCase(),
      htu: url,
      ath: await accessTokenHash(accessToken),
    })
      .setProtectedHeader({
        alg: "ES256",
        typ: "dpop+jwt",
        jwk: input.publicJwk,
      })
      .setIssuedAt()
      .setJti(crypto.randomUUID())
      .setExpirationTime("1m")
      .sign(input.privateKey);
}
