const encode = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

/** Store this attempt in sessionStorage before navigating. It contains the secret PKCE verifier. */
export async function createSignInRequest(input: { clientId: string; redirectUri: string; scopes: string[]; theme?: "light" | "dark"; product?: "notorganic" | "keating" | "twyne" | "interleave" | "stich" }): Promise<SignInAttempt> {
  const client = new URL(input.clientId), callback = new URL(input.redirectUri);
  const loopback = client.protocol === "http:" && ["localhost", "127.0.0.1", "[::1]"].includes(client.hostname);
  if ((!loopback && client.protocol !== "https:") || client.href !== client.origin + "/" || client.username || client.password || callback.origin !== client.origin || callback.hash || callback.searchParams.has("code") || callback.searchParams.has("state") || callback.username || callback.password) throw new Error("Use an HTTPS app origin and a callback on the same origin.");
  if (!input.scopes.length || input.scopes.some(scope => !/^[a-z][a-z0-9:_-]+$/.test(scope))) throw new Error("Select explicit permission scopes.");
  const verifier = encode(crypto.getRandomValues(new Uint8Array(32)));
  const state = encode(crypto.getRandomValues(new Uint8Array(32)));
  const challenge = encode(new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier))));
  const url = new URL("https://id.notorganic.info/authorize");
  url.search = new URLSearchParams({ response_type: "code", client_id: client.origin, redirect_uri: callback.href, code_challenge_method: "S256", code_challenge: challenge, state, scope: [...new Set(input.scopes)].join(" "), ...(input.theme ? { theme: input.theme } : {}), ...(input.product ? { product: input.product } : {}) }).toString();
  return { url: url.href, clientId: client.origin, redirectUri: callback.href, verifier, state, expiresAt: Date.now() + 600_000 };
}

/** Consume the stored attempt once before calling. Returned credentials stay in memory. */
export async function completeSignIn(attempt: SignInAttempt, callbackUrl: string): Promise<BrowserClient> {
  const callback = new URL(callbackUrl), expected = new URL(attempt.redirectUri);
  if (!Number.isFinite(attempt.expiresAt) || Date.now() >= attempt.expiresAt || callback.origin !== expected.origin || callback.pathname !== expected.pathname || callback.hash || callback.searchParams.getAll("state").length !== 1 || callback.searchParams.get("state") !== attempt.state || callback.searchParams.getAll("code").length !== 1 || !callback.searchParams.get("code") || callback.searchParams.has("error")) throw new Error("Sign-in did not match this attempt. Start again.");
  for (const [key, value] of expected.searchParams) if (callback.searchParams.getAll(key).length !== 1 || callback.searchParams.get(key) !== value) throw new Error("The callback address changed. Start sign-in again.");
  const keys = await createDpopKeyPair();
